292	    private static boolean isBlank(String value) {
293	        return value == null || value.trim().isEmpty();
294	    }
295	
296	    /**
297	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
298	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
299	     * compared case-insensitively with collapsed whitespace.
300	     */
301	    private static String collapse(String value) {
302	        if (value == null) {
303	            return "";
304	        }
305	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
306	    }
307	
308	    /**
309	     * Common street-type abbreviations expanded during address normalization.
310	     */
311	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
312	        "ST", "STREET",
313	        "RD", "ROAD",
314	        "AVE", "AVENUE");
315	
316	    /**
317	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
318	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
319	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
320	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
321	     * address maps to itself.
322	     */
323	    private static String normalizeAddress(String value) {
324	        if (value == null) {
325	            return "";
326	        }
327	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
328	        if (collapsed.isEmpty()) {
329	            return "";
330	        }
331	        String[] tokens = collapsed.split(" ");
332	        StringBuilder sb = new StringBuilder(collapsed.length());
333	        for (int i = 0; i < tokens.length; i++) {
334	            if (i > 0) {
335	                sb.append(' ');
336	            }
337	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
338	        }
339	        return sb.toString();
340	    }
341	
342	    /**
343	     * Derive the stable household identifier shared by owners with the same normalized last name
344	     * and address. It is a deterministic function of those two values, so every member of a
345	     * household independently derives the same identifier: the first 12 upper-case hex characters
346	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
347	     */
348	    private static String householdId(String normalizedLastName, String normalizedAddress) {
349	        try {
350	            byte[] digest = MessageDigest.getInstance("SHA-256")
351	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
352	            StringBuilder sb = new StringBuilder(digest.length * 2);
353	            for (byte b : digest) {
354	                sb.append(String.format("%02x", b));
355	            }
356	            return sb.substring(0, 12).toUpperCase();
357	        }
358	        catch (NoSuchAlgorithmException e) {
359	            throw new IllegalStateException("SHA-256 not available", e);
360	        }
361	    }
362	
363	    /**
364	     * Build the customer code for a new owner: {@code '<LAST3>-<NNNN>'} where LAST3 is the
365	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
366	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
367	     */
368	    private String nextCustomerCode(String lastName) {
369	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
370	        long sequence = this.clinicService.findAllOwners().size() + 1L;
371	        return String.format("%s-%04d", last3, sequence);
372	    }
373	
374	    /**
375	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
376	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
377	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
378	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
379	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
380	     */
381	    private static String toE164(String raw) {
382	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
383	        boolean hasCountryCode = cleaned.startsWith("+");
384	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
385	        if (!digits.matches("\\d+")) {
386	            throw new InvalidOwnerFieldsException(List.of("telephone"));
387	        }
388	        if (!hasCountryCode) {
389	            if (digits.startsWith("0")) {
390	                digits = digits.substring(1);
391	            }
392	            digits = "61" + digits;
393	        }
394	        if (digits.length() < 8 || digits.length() > 15) {
395	            throw new InvalidOwnerFieldsException(List.of("telephone"));
396	        }
397	        return "+" + digits;
398	    }
399	
400	    /**
401	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
402	     * and a domain with at least one dot-separated label, none of which contain whitespace or
403	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
404	     */
405	    private static final Pattern EMAIL_PATTERN =
406	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
407	
408	    /**
409	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
410	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
411	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
412	     * 400. A valid address is returned lower-cased.
413	     */
414	    private static String normalizeEmail(String email) {
415	        if (email == null || email.isEmpty()) {
416	            return null;
417	        }
418	        String trimmed = email.trim();
419	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
420	            throw new InvalidOwnerFieldsException(List.of("email"));
421	        }
422	        return trimmed.toLowerCase();
423	    }
